using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1) GetTypeInfo<T>: strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> returned type: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2) TryGetTypeInfo<T>: probe without throwing ---

// 2a) With a default resolver the type IS resolvable:
if (options.TryGetTypeInfo<Person>(out var resolved))
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded – type: {resolved!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Person> returned false");

// 2b) With a *source-gen-only* context, an un-registered type is NOT resolvable:
var strict = new JsonSerializerOptions { TypeInfoResolver = new EmptyContext() };

if (strict.TryGetTypeInfo<Person>(out var missing))
    Console.WriteLine($"Unexpected: resolved {missing!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Person> on empty context returned false (no exception)");

// --- Types ---
public record Person(string Name, int Age);

/// A deliberately empty context so nothing resolves.
[JsonSerializable(typeof(int))]          // register *something* so the context is valid
public partial class EmptyContext : JsonSerializerContext;

